mapper.select:
select r.*,p.project_name,i.image_name,rr.review_content as content,tr.round_name,g.group_name,tt.topic_name from tb_review r left join tb_project p on r.project_id = p.project_id left join tb_slide s on r.slide_id = s.slide_id left join tb_image i on s.image_id = i.image_id left join tb_review_round rr on s.review_round_id = rr.review_round_id left join tb_round tr on rr.round_id = tr.round_id left join tb_group g on rr.group_id = g.group_id left join tb_topic tt on rr.topic_id = tt.topic_id
AND s.project_id = #{params.projectId}
AND s.slide_id = #{params.slideId}

SELECT rr.*,g.group_name,t.topic_name,r.round_name,u.user_name as create_by_name FROM tb_review_round rr LEFT JOIN tb_project p ON rr.project_id = p.project_id LEFT JOIN tb_group g ON g.group_id = rr.group_id LEFT JOIN tb_topic t ON t.topic_id = rr.topic_id LEFT JOIN tb_round r ON r.round_id = rr.round_id LEFT JOIN sys_user u ON u.user_id = rr.create_by
AND p.project_id = #{params.projectId}
AND rr.round_id = #{params.roundId}
AND rr.group_id = #{params.groupId}
AND t.topic_name like CONCAT('%',#{params.topicName},'%')
AND rr.review_content like CONCAT('%',#{params.reviewContent},'%')
